  (hG : (X : C) → CategoryTheory.Limits.IsLimit ((data X).toOneHypercover.multifork G)) {X : C} {S : J.Cover X}
  (s : CategoryTheory.Limits.Multifork (S.index G)) (a : S.Arrow),
  CategoryTheory.CategoryStruct.comp (CategoryTheory.Functor.OneHypercoverDenseData.isSheaf_iff.lift✝ hG₀ hG s)
      (G.map a.f.op) =
    s.ι a

helperStatement:
∀ {K : Type u_1} {Γ : K → Type u_2} {Λ : Type u_3} {σ : Type u_4} [inst : DecidableEq K] {k : K}
  {q : Turing.TM1.Stmt (Turing.TM2to1.Γ' K Γ) (Turing.TM2to1.Λ' K Γ Λ σ) σ} {v : σ} {S : (k : K) → List (Γ k)}
  {L : Turing.ListBlank ((k : K) → Option (Γ k))},
  (∀ (k : K), Turing.ListBlank.map (Turing.proj k) L = Turing.ListBlank.mk (List.map some (S k)).reverse) →
    ∀ (o : Turing.TM2to1.StAct K Γ σ k),
      have v' := Turing.TM2to1.stVar v (S k) o;
      have Sk' := Turing.TM2to1.stWrite v (S k) o;
      have S' := Function.update S k Sk';
      ∃ L',
        (∀ (k : K), Turing.ListBlank.map (Turing.proj k) L' = Turing.ListBlank.mk (List.map some (S' k)).reverse) ∧
          Turing.TM1.stepAux (Turing.TM2to1.trStAct q o) v
              ((Turing.Tape.move Turing.Dir.right)^[(S k).length] (Turing.Tape.mk' ∅ (Turing.TM2to1.addBottom L))) =
            Turing.TM1.stepAux q v'
              ((Turing.Tape.move Turing.Dir.right)^[(S' k).length] (Turing.Tape.mk' ∅ (Turing.TM2to1.addBottom L')))

