∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {E : Type u_2} {E''' : Type u_4} {E'' : Type u} {F : Type u_5}
  [inst_1 : NormedAddCommGroup E] [inst_2 : NormedSpace 𝕜 E] [inst_3 : NormedAddCommGroup E'']
  [inst_4 : NormedSpace 𝕜 E''] [inst_5 : NormedAddCommGroup E'''] [inst_6 : NormedSpace 𝕜 E''']
  [inst_7 : NormedAddCommGroup F] [inst_8 : NormedSpace 𝕜 F] {H : Type u_7} [inst_9 : TopologicalSpace H] {G : Type u_9}
  [inst_10 : TopologicalSpace G] {G' : Type u_10} [inst_11 : TopologicalSpace G'] {I : ModelWithCorners 𝕜 E H}
  {J : ModelWithCorners 𝕜 E'' G} {J' : ModelWithCorners 𝕜 E''' G'} {M : Type u_11} [inst_12 : TopologicalSpace M]
  [inst_13 : ChartedSpace H M] {N : Type u_13} [inst_14 : TopologicalSpace N] [inst_15 : ChartedSpace G N]
  {N' : Type u_14} [inst_16 : TopologicalSpace N'] [inst_17 : ChartedSpace G' N'] {n : WithTop ℕ∞} {x : M} {f : M → N}
  {φ : N → N'},
  Manifold.IsImmersionAtOfComplement F J J' n φ (f x) →
    (ContMDiffAt I J n f x ↔ ContinuousAt f x ∧ ContMDiffAt I J' n (φ ∘ f) x)

∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {H : Type u_2} [inst_1 : TopologicalSpace H] {E : Type u_3}
  [inst_2 : NormedAddCommGroup E] [inst_3 : NormedSpace 𝕜 E] {I : ModelWithCorners 𝕜 E H} {M : Type u_4}
  [inst_4 : TopologicalSpace M] [inst_5 : ChartedSpace H M] {s : Set M} {x : M} {V W : (x : M) → TangentSpace I x}
  [IsManifold I 2 M] {f : M → 𝕜},
  MDiffAt[s] f x →
    have V' := VectorField.mpullbackWithin (modelWithCornersSelf 𝕜 E) I (↑(extChartAt I x).symm) V (Set.range ↑I);
    have W' := VectorField.mpullbackWithin (modelWithCornersSelf 𝕜 E) I (↑(extChartAt I x).symm) W (Set.range ↑I);
    VectorField.mpullback I (modelWithCornersSelf 𝕜 E) (↑(extChartAt I x))
        (fun x₀ =>
          (fderivWithin 𝕜 (f ∘ ↑(extChartAt I x).symm) (↑(extChartAt I x).symm ⁻¹' s ∩ Set.range ↑I) x₀) (V' x₀) •
            W' x₀)
        x =
      (mfderiv[s] f x) (V x) • W x

